import SwiftUI
import AuthenticationServices
@MainActor final class WorkerStore: NSObject, ObservableObject, ASWebAuthenticationPresentationContextProviding {
    @Published var baseAddress = UserDefaults.standard.string(forKey:"siteguard.server") ?? "http://127.0.0.1:3001"
    @Published var config: AuthConfig?
    @Published var identity: Identity?
    @Published var workers: [Worker] = []
    @Published var breaks: [ProtectedBreak] = []
    @Published var history: [Session] = []
    @Published var activeSession: Session?
    @Published var readings: [ReadingEnvelope] = []
    @Published var summary: Summary?
    @Published var busy = false
    @Published var error = ""
    @Published var notice = ""
    private var browser: ASWebAuthenticationSession?
    private var token = SecureToken.read()
    private var client: APIClient { get throws { guard let url = URL(string:baseAddress), let host = url.host, url.user == nil, url.password == nil, url.query == nil, url.fragment == nil, url.path.isEmpty || url.path == "/", url.scheme == "https" || (url.scheme == "http" && ["127.0.0.1","localhost"].contains(host)) else { throw ClientError.message("Use an HTTPS server address. HTTP is allowed only for this computer's simulator loopback.") }; return APIClient(baseURL:url,token:token) } }
    var currentBreak: ProtectedBreak? { breaks.first { $0.kind == "protected" && (parseDate($0.startsAt) ?? .distantFuture) <= Date() && (parseDate($0.endsAt) ?? .distantPast) > Date() } }
    func perform(_ work: () async throws -> Void) async { guard !busy else { return }; busy = true; error = ""; notice = ""; defer { busy = false }; do { try await work() } catch { self.error = error.localizedDescription; if case ClientError.expired = error { clearIdentity() } } }
    func connect() async { await perform { let api = try client; let settings: AuthConfig = try await api.request("/auth/config"); self.config = settings; UserDefaults.standard.set(baseAddress,forKey:"siteguard.server"); let me: IdentityResponse = try await api.request("/auth/me"); identity = me.identity; if identity?.role == "worker" { try await refreshRecords() } else if identity == nil && settings.mode == "demo" { let roster: WorkersResponse = try await api.request("/workers"); workers = roster.workers } } }
    func demoLogin(_ workerId: String) async { await perform { let _: Identity = try await client.request("/demo/login",body:["role":"worker","workerId":workerId]); let me: IdentityResponse = try await client.request("/auth/me"); identity = me.identity; try await refreshRecords() } }
    func refreshRecords() async throws { guard let workerId = identity?.workerId else { return }; let api = try client; let b: BreaksResponse = try await api.request("/breaks"); let h: HistoryResponse = try await api.request("/workers/\(workerId)/history?limit=20"); breaks = b.breaks; history = h.sessions; if let id = UserDefaults.standard.string(forKey:"siteguard.active.\(workerId)") { do { let s: SessionResponse = try await api.request("/sessions/\(id)"); if s.session.status == "active" { activeSession = s.session } else { UserDefaults.standard.removeObject(forKey:"siteguard.active.\(workerId)"); activeSession = nil } } catch ClientError.expired { throw ClientError.expired } catch { UserDefaults.standard.removeObject(forKey:"siteguard.active.\(workerId)") } } }
    func refresh() async { await perform { try await refreshRecords() } }
    func start(share: Bool, workload: String, temperature: String) async { await perform { guard let protectedBreak = currentBreak else { throw ClientError.message("A current protected break is required.") }; let temp: Any; if temperature.isEmpty { temp = NSNull() } else if let number = Double(temperature), number.isFinite { temp = number } else { throw ClientError.message("Enter a valid temperature or leave it empty.") }; let response: SessionResponse = try await client.request("/sessions",body:["breakId":protectedBreak.id,"source":"mock","consentVersion":"v1","shareWithSupervisor":share,"context":["workload":workload.isEmpty ? NSNull() : workload as Any,"temperatureC":temp]]); activeSession = response.session; readings = []; summary = nil; if let workerId = identity?.workerId { UserDefaults.standard.set(response.session.id,forKey:"siteguard.active.\(workerId)") } } }
    func poll() async { guard let session = activeSession else { return }; do { let r: ReadingsResponse = try await client.request("/sessions/\(session.id)/readings"); readings = r.readings } catch { self.error = error.localizedDescription; if case ClientError.expired = error { clearIdentity() } } }
    func complete() async { await perform { guard let session = activeSession else { return }; let result: SummaryResponse = try await client.request("/sessions/\(session.id)/complete",body:[:]); summary = result.summary; activeSession = nil; if let workerId = identity?.workerId { UserDefaults.standard.removeObject(forKey:"siteguard.active.\(workerId)") }; try await refreshRecords() } }
    func loadSummary(_ session: Session) async { await perform { let result: SummaryResponse = try await client.request("/sessions/\(session.id)/summary"); summary = result.summary } }
    func requestHelp(kind: String, minutes: Int = 5) async { await perform { let _: EmptyResponse = try await client.request("/rest-requests",body:["sessionId":activeSession?.id as Any? ?? NSNull(),"kind":kind,"requestedMinutes":kind == "assistance" ? NSNull() : minutes as Any]); notice = kind == "assistance" ? "Assistance request recorded. Your manager must respond." : "Additional-rest request recorded. Approval is pending." } }
    func reportSymptom(code: String, note: String) async { await perform { let _: EmptyResponse = try await client.request("/symptom-reports",body:["sessionId":activeSession?.id as Any? ?? NSNull(),"codes":[code],"note":note.isEmpty ? NSNull() : note as Any]); notice = "Symptom report and assistance request recorded." } }
    func logout() async { await perform { let _: EmptyResponse = try await client.request("/auth/logout",body:[:]); clearIdentity(); config = nil } }
    private func clearIdentity() { token = nil; SecureToken.clear(); identity = nil; breaks = []; history = []; activeSession = nil; readings = []; summary = nil; HTTPCookieStorage.shared.cookies?.forEach { HTTPCookieStorage.shared.deleteCookie($0) } }
    func signIn() { guard !busy else { return }; do { let api = try client; let verifier = pkceVerifier(); let url = api.baseURL.appendingPathComponent("api/auth/mobile/start").appending(queryItems:[URLQueryItem(name:"challenge",value:pkceChallenge(verifier))]); error = ""; busy = true; browser = ASWebAuthenticationSession(url:url,callbackURLScheme:"siteguard-worker") { [weak self] callback,error in Task { @MainActor in guard let self else { return }; self.busy = false; guard let callback, let components = URLComponents(url:callback,resolvingAgainstBaseURL:false), let code = components.queryItems?.first(where:{$0.name == "code"})?.value else { self.error = error?.localizedDescription ?? "Sign-in did not finish."; return }; await self.perform { let exchanged: ExchangeResponse = try await api.request("/auth/mobile/exchange",body:["code":code,"verifier":verifier]); try SecureToken.save(exchanged.token); self.token = exchanged.token; let me: IdentityResponse = try await self.client.request("/auth/me"); self.identity = me.identity; if self.identity?.role == "worker" { try await self.refreshRecords() } } } }; browser?.presentationContextProvider = self; browser?.prefersEphemeralWebBrowserSession = true; guard browser?.start() == true else { busy = false; throw ClientError.message("Unable to open secure sign-in.") } } catch { self.error = error.localizedDescription } }
    func presentationAnchor(for session: ASWebAuthenticationSession) -> ASPresentationAnchor { UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }.flatMap(\.windows).first(where:\.isKeyWindow) ?? ASPresentationAnchor() }
}
